{
    "jsonrpc": "2.0",
    "method": "call",
    "params": {
        "service": "object",
        "method": "execute",
        "args": [
            "{{db_name}}",
            {{user_id}},
            "{{user_passwd}}",
            "stock.check.connector",
            "external_stock_check",
            {
                "ecommerceId": {{ecommerce_id}},
                "companyId": {{company_id}},
                "lotSerialSearch": "all",  // ["all", "available"]
                "lotSerialDate": "2000-01-01",  // en caso de que la opción anterior sea all, mostrar lotes/números de serie sin unidades a patir de esa fecha
                "products":[  // (si no se indica, se buscan todos los productos)
                    {
                        "searchKey": "ecommerceId",  //  ["odooId", "ecommerceId", "sku", "barcode"] (método de búsqueda del producto),
                        "searchVal": "100"  
                    },
                    {
                        "searchKey": "sku",
                        "searchVal": "100_sku"
                    },
                    {
                        "searchKey": "barcode",
                        "searchVal": "100_barcode"
                    }
                ]
            }
        ]
    }
}
